 array['الفحص المخبري الشامل والدموي','العمليات الجراحية المتقدمة والعظام','الأشعة والتشخيص السوناري المتقدم','قسم خاص للإيواء الفندقي الآمن','صيدلية بيطرية متكاملة ومستوردة'],
 array['https://images.unsplash.com/photo-1628009368231-7bb7cfcb0def?w=600&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1517841905240-472988babdf9?w=600&auto=format&fit=crop&q=80']),
('clinic-3', 'عيادة عدن لرعاية وعلاج الحيوانات الأليفة', 'عدن', '+967733221199', 'عدن - المنصورة، شارع التسعين، بجانب بنك اليمن والكويت', 4.7, true,
 'العيادة الأولى المتخصصة في مدينة عدن لتقديم الرعاية الطبية الشاملة والمتميزة للحيوانات الأليفة مع توفير الرعاية الطارئة والإيواء المؤقت للحالات الحرجة.',
 'من السبت إلى الخميس: 8:30 صباحاً - 9:30 مساءً (الطوارئ متاحة على الهاتف)',
 array['العيادات الطبية والاستشارات المنزلية','جراحة الأنسجة الرخوة والتعقيم','تركيب الشرائح الإلكترونية والشهادات الصحية','مستلزمات وأغذية الحيوانات الأليفة','تحصين ضد السعار والرباعي القطط'],
 array['https://images.unsplash.com/photo-1599443015574-be5fe8a3859b?w=600&auto=format&fit=crop&q=80','https://images.unsplash.com/photo-1606425271394-c3ca9a1fc0ae?w=600&auto=format&fit=crop&q=80']),
('clinic-4', 'مستوصف الرحمة البيطري', 'تعز', '+967711998877', 'تعز - شارع الحصب، أمام الصيدلية الكبرى', 4.5, false,
 'مستوصف الرحمة يهدف إلى توفير علاج ورعاية بيطرية رحيمة وبأسعار مناسبة لتكون في متناول الجميع، مع تقديم دعم مخصص للمتبنين وفرق الإنقاذ.',
 'يومياً عدا الجمعة: 9:00 صباحاً - 8:30 مساءً',
 array['الفحص الإكلينيكي والعلاج الدوائي','جراحات التعقيم والإصابات','صيدلية الأدوية البيطرية المتكاملة','نصائح التغذية والرعاية السليمة'],
 array['https://images.unsplash.com/photo-1583337130417-3346a1be7dee?w=600&auto=format&fit=crop&q=80']),
('clinic-5', 'صيدلية وعيادة حضرموت البيطرية', 'حضرموت', '+967705544332', 'المكلا - الديس، الشارع العام، جوار عمارة باجابر', 4.6, false,
 'نوفر الرعاية الأساسية والأدوية واللقاحات الهامة لحيواناتكم الأليفة ومواشيكم في ساحل حضرموت، بخبرة تمتد لسنوات طويلة.',
