insert into public.clinic_comments (id, clinic_id, author_name, rating, text, created_at) values
('c-1-1','clinic-1','محمد الريمي',5,'عيادة ممتازة جداً ونظيفة، تعامل الدكتور كان في غاية اللطف وقاموا بإنقاذ قطتي بعد تعرضها للتسمم.','2026-06-25T14:30:00Z'),
