insert into public.community_posts (id, title, content, author, likes, comments_count, category, created_at) values
('post-1', 'كيف تحمي حيوانك الأليف من حرارة الصيف الشديدة في المدن الساحلية مثل عدن والحديدة؟',
 'الصيف في اليمن يكون شديد الحرارة خصوصاً في المناطق الساحلية. إليك أهم النصائح لحماية قطتك أو كلبك:
1. توفير المياه الباردة والنظيفة طوال 24 ساعة في أكثر من مكان بالمنزل.
2. تشغيل المروحة أو التكييف في الغرفة التي يتواجد بها الحيوان وتجنب تركه في الأماكن المغلقة تماماً.
3. عدم تمشية الكلاب على الإسفلت الساخن خلال النهار لأنه يسبب حروقاً شديدة لوسادات أقدامهم.
4. تمشيط الفرو بانتظام لإزالة الشعر الميت الذي يحبس الحرارة داخل الجسم.
5. مراقبة علامات الإجهاد الحراري مثل اللهث الشديد والخمول التام، وفي هذه الحالة امسح جسمه بقطعة قماش مبللة بماء فاتر وتوجه فوراً للطبيب البيطري.',
 'د. نجيب اليماني (طبيب بيطري)', 42, 15, 'tips', '2026-06-29T11:00:00Z'),
('post-2', 'قصة نجاح سعيدة: تبني القطة الضريرة ''بسبوسة'' وإعادة الأمل لها',
 'قبل شهرين، عثرنا على قطة صغيرة في شوارع صنعاء القديمة تعاني من التهاب شديد في العينين أدى إلى فقدان بصرها، وكانت خائفة وجائعة للغاية. قمنا بنشر حالتها على منصة أليف، وتواصلت معنا الأخت الكريمة أروى التي قررت تبنيها بالرغم من حالتها الخاصة.
اليوم بسبوسة تعيش حياة الملوك! لقد أخذتها أروى للطبيب وتم علاج الالتهاب، ورغم أنها لا ترى إلا أنها تحفظ زوايا المنزل تماماً وتلعب وتمرح بحب كبير. التبني ينقذ الأرواح، لا تترددوا في إعطاء فرصة للحيوانات ذات الاحتياجات الخاصة.',
 'أروى الهمداني & فريق أليف', 89, 24, 'stories', '2026-07-01T15:20:00Z'),
('post-3', 'أفضل مصادر الغذاء الصحي والاقتصادي للقطط والكلاب المتوفرة محلياً في اليمن',
 'مع ارتفاع أسعار الدراي فود المستورد، يبحث الكثير عن بدائل صحية واقتصادية متوفرة في المطبخ اليمني:
- للقطط: صدور الدجاج المسلوقة جيداً بدون ملح أو بهارات.
- كبدة الدجاج المسلوقة بماء فقط (مرة أو مرتين أسبوعياً).
- سمك التونة المعلب بالماء (يغسل جيداً من الزيت أو الملح الزائد).
- الشوفان المطبوخ بمرق الدجاج (الخالي من البصل والثوم والملح).
تنبيه هام جداً: البصل، الثوم، الشوكولاتة، والعنب هي سموم قاتلة للقطط والكلاب، تجنب تقديمها تماماً!',
 'رغد السقاف (مربية خبيرة)', 56, 11, 'tips', '2026-07-02T01:00:00Z')
on conflict (id) do nothing;
